/*
 * A105413  Primes p = prime(k) such that both p+2 and prime(k+6)-2 are prime
 *          numbers.
 * https://oeis.org/A105413
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth prime p=prime(k) such that p+2 is prime and
 *            prime(k+6)-2 is prime. The sequence is generated by scanning the
 *            list of primes and keeping those that satisfy the two
 *            conditions. The implementation builds an increasing sieve and
 *            collects the qualifying primes until the requested index...
 * Range:     u8 n <= 4, u16 n <= 104, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <math.h>

static uint32_t *primes = NULL;          /* list of primes up to current_limit  */
static size_t primes_cnt = 0;            /* number of primes stored           */
static uint32_t *good_primes = NULL;     /* qualifying primes (seq value)     */
static size_t good_cnt = 0;              /* number of qualifying primes       */
static uint8_t *is_prime_arr = NULL;     /* boolean array of primality       */
static uint32_t current_limit = 0;       /* current maximum sieved value      */

/* Sieve of Eratosthenes up to new_limit and rebuild lists. */
static void compute_upto(uint32_t new_limit)
{
    /* free old data */
    if (is_prime_arr) free(is_prime_arr);
    if (primes)       free(primes);
    if (good_primes)  free(good_primes);

    /* allocate primality array */
    is_prime_arr = (uint8_t*)calloc(new_limit + 1, sizeof(uint8_t));
    for (uint32_t i = 2; i <= new_limit; ++i) is_prime_arr[i] = 1;

    /* sieve */
    uint32_t r = (uint32_t)sqrt((double)new_limit);
    for (uint32_t i = 2; i <= r; ++i) {
        if (is_prime_arr[i]) {
            for (uint32_t j = i * i; j <= new_limit; j += i)
                is_prime_arr[j] = 0;
        }
    }

    /* build primes array */
    primes_cnt = 0;
    /* initial capacity estimate */
    size_t prime_cap = new_limit / log((double)new_limit) + 10;
    primes = (uint32_t*)malloc(prime_cap * sizeof(uint32_t));
    for (uint32_t i = 2; i <= new_limit; ++i) {
        if (is_prime_arr[i]) {
            if (primes_cnt == prime_cap) {
                prime_cap *= 2;
                primes = (uint32_t*)realloc(primes, prime_cap * sizeof(uint32_t));
            }
            primes[primes_cnt++] = i;
        }
    }

    /* build qualifying primes array */
    good_cnt = 0;
    size_t good_cap = primes_cnt / 10 + 10;
    good_primes = (uint32_t*)malloc(good_cap * sizeof(uint32_t));

    for (size_t idx = 0; idx + 6 < primes_cnt; ++idx) {
        uint32_t p = primes[idx];
        uint32_t p_plus2 = p + 2;
        if (p_plus2 > new_limit || !is_prime_arr[p_plus2]) continue;

        uint32_t q = primes[idx + 6];
        uint32_t q_minus2 = q - 2;
        if (q_minus2 > new_limit || !is_prime_arr[q_minus2]) continue;

        if (good_cnt == good_cap) {
            good_cap *= 2;
            good_primes = (uint32_t*)realloc(good_primes, good_cap * sizeof(uint32_t));
        }
        good_primes[good_cnt++] = p;
    }

    current_limit = new_limit;
}

/* Public function requested by the task */
seq_t a(idx_t n)
{
    if (n == 0) return 0;  /* undefined for offset 0, but harmless */

    /* initialise on first call */
    static uint32_t init_limit = 1000000;  /* start with 1 million */
    static int initialized = 0;
    if (!initialized) {
        compute_upto(init_limit);
        initialized = 1;
    }

    /* grow sieve until we have enough good primes */
    while (good_cnt < (size_t)n) {
        uint32_t new_limit = current_limit * 2;
        if (new_limit <= current_limit) new_limit = current_limit + 1000000; /* avoid overflow */
        compute_upto(new_limit);
    }

    return (seq_t)good_primes[n - 1];
}
